import re
from dataclasses import dataclass, field
from collections.abc import Iterable

from .models import Arrival, ArrivalBoard, DirectionBoard, Line, Station, TflPrediction


DIRECTIONS = ("Northbound", "Eastbound", "Southbound", "Westbound")
PLATFORM_PATTERN = re.compile(r"platform\s+([0-9]+[A-Za-z]?)", re.IGNORECASE)


@dataclass
class MergedArrival:
    vehicle_key: str
    destination_name: str
    time_to_station: int
    platforms: set[str] = field(default_factory=set)


class ArrivalBoardService:
    def build_board(
        self,
        station: Station,
        line: Line,
        predictions: list[TflPrediction],
    ) -> ArrivalBoard:
        grouped: dict[str, dict[str, MergedArrival]] = {
            direction: {} for direction in DIRECTIONS
        }

        for direction, prediction in self._board_predictions(station, line, predictions):
            self._merge_prediction(grouped, direction, prediction)

        boards = self._to_direction_boards(grouped)
        return ArrivalBoard(station=station, line=line, directions=boards)

    def _board_predictions(
        self,
        station: Station,
        line: Line,
        predictions: Iterable[TflPrediction],
    ) -> Iterable[tuple[str, TflPrediction]]:
        for prediction in predictions:
            if not self._belongs_to_board(prediction, station, line):
                continue

            direction = self._direction_from_platform(prediction.platform_name)
            if direction is not None:
                yield direction, prediction

    def _merge_prediction(
        self,
        grouped: dict[str, dict[str, MergedArrival]],
        direction: str,
        prediction: TflPrediction,
    ) -> None:
        vehicle_key = prediction.vehicle_id or f"prediction:{id(prediction)}"
        arrival = grouped[direction].get(vehicle_key)
        if arrival is None:
            grouped[direction][vehicle_key] = MergedArrival(
                vehicle_key=vehicle_key,
                destination_name=prediction.destination_name or "Unknown destination",
                time_to_station=self._normalized_time(prediction.time_to_station),
                platforms=self._platforms_from_prediction(prediction),
            )
            return

        arrival.time_to_station = min(
            arrival.time_to_station,
            self._normalized_time(prediction.time_to_station),
        )
        if arrival.destination_name == "Unknown destination" and prediction.destination_name:
            arrival.destination_name = prediction.destination_name
        arrival.platforms.update(self._platforms_from_prediction(prediction))

    def _to_direction_boards(
        self,
        grouped: dict[str, dict[str, MergedArrival]],
    ) -> list[DirectionBoard]:
        return [
            DirectionBoard(
                direction=direction,
                arrivals=self._to_arrivals(grouped[direction].values()),
            )
            for direction in DIRECTIONS
            if grouped[direction]
        ]

    def _belongs_to_board(
        self,
        prediction: TflPrediction,
        station: Station,
        line: Line,
    ) -> bool:
        return prediction.naptan_id == station.id and prediction.line_id == line.id

    def _direction_from_platform(self, platform_name: str | None) -> str | None:
        if not platform_name:
            return None
        platform = platform_name.casefold()
        return next(
            (direction for direction in DIRECTIONS if direction.casefold() in platform),
            None,
        )

    def _platform_number(self, platform_name: str | None) -> str | None:
        if not platform_name:
            return None
        match = PLATFORM_PATTERN.search(platform_name)
        return match.group(1) if match else None

    def _platforms_from_prediction(self, prediction: TflPrediction) -> set[str]:
        platform = self._platform_number(prediction.platform_name)
        return {platform} if platform else set()

    def _normalized_time(self, seconds: int | None) -> int:
        return max(seconds or 0, 0)

    def _to_arrivals(self, arrivals: Iterable[MergedArrival]) -> list[Arrival]:
        sorted_arrivals = sorted(
            arrivals,
            key=lambda arrival: (
                arrival.time_to_station,
                arrival.destination_name.casefold(),
                arrival.vehicle_key,
            ),
        )
        return [
            Arrival(
                index=index,
                destination_name=arrival.destination_name,
                time_to_station=arrival.time_to_station,
                display_time=self._display_time(arrival.time_to_station),
                platform_numbers=self._platform_numbers(arrival.platforms),
            )
            for index, arrival in enumerate(sorted_arrivals, start=1)
        ]

    def _display_time(self, seconds: int) -> str:
        if seconds < 30:
            return "Due"
        return f"{max(1, seconds // 60)} min"

    def _platform_numbers(self, platforms: set[str]) -> str:
        if not platforms:
            return "-"
        return ",".join(sorted(platforms, key=self._platform_sort_key))

    def _platform_sort_key(self, platform: str) -> tuple[int, str]:
        match = re.match(r"(\d+)(.*)", platform)
        if match is None:
            return (10_000, platform)
        return (int(match.group(1)), match.group(2))
